WFJ.Data.add("gossip", {
  ["fe03921642f6fd32"] = { "Attenti a {name}!", "." },
  ["fe0699d652a34bc1"] = { "Ti prometto un'eternità di pulizia dello sterco per quel fallimento!", "." },
  ["fe0eccd4d36f5e89"] = { "Può sembrare semplice, un grosso bastone con un enorme peso in cima. Ma quando lo brandisce tutta la forza di un tauren, questo bastone può abbattere muri di pietra.", "." },
  ["fe14e0379d624305"] = { "Se non verranno presto inviati altri rinforzi nelle ⟦Burning Steppes=Steppe Ardenti⟧, temo che il Flagello vi stabilirà una base operativa. Se puoi, dovresti andare là ad aiutare i difensori.\n\nNecropoli rimanenti: $2281W", "." },
  ["fe17077adc396378"] = { "Non posso aiutarti a proseguire l'addestramento: la tua abilità nel lavorare il cuoio rivaleggia con la mia. Dovresti parlare con ⟦Una=Uma⟧, laggiù. Se serve, garantirò io per la tua abilità.", "." },
  ["fe1b7e6e89265652"] = { "Le gilde dell'⟦Horde=Orda⟧ hanno unito le forze e hanno già portato a termine questo compito, {class}. Abbiamo tutte le Pietre del Nucleo Carbonizzate necessarie per il nostro materiale bellico. Renditi utile chiedendo agli altri raccoglitori qui se hanno bisogno del tuo aiuto.", "." },
  ["fe28fda6dffc7c09"] = { "Stai facendo strada... ormai sei più in alto di me! Dovresti parlare con ⟦Springspindle Fizzlegear=Frizzaruota⟧ a ⟦Ironforge=Forgiardente⟧! (Lui? Lei?) ti mostrerà più di quanto potrei mai fare io!", "." },
  ["fe2ed41cded7d458"] = { "%s va su tutte le furie dopo aver visto Misha cadere in battaglia!", "." },
  ["fe484e3cf1079ba0"] = { "%s pronuncia parole di potere...", "." },
  ["fe4aff8efc202340"] = { "%s si sbriciola in polvere.", "." },
  ["fe4b966b28b3de4c"] = { "So molte cose, ma la vera esperta è un'altra. Sai con chi dovresti parlare? Con Rhiannon! Non è lontana. Chiedi di lei a ⟦Undercity=Sepulcra⟧", "." },
  ["fe4ba8b6cb28f779"] = { "Ok, chi mi ha spinto giù? Sei <stato/stata> tu, {name}? Qualcuno riaccenda le luci. Hic!", "." },
  ["fe4e1ed75e7425fd"] = { "Ti suggerirei di cercare nella ⟦Cathedral of Light=Cattedrale della Luce⟧, in Cathedral Square.", "." },
  ["fe5b8003e7b4d513"] = { "Accidenti, mi dispiace. Non ho niente di nuovo da insegnarti. Perché non vai a parlare con Simon Tanner, nella Old Town di ⟦Stormwind=Roccavento⟧? È un umano con grandi muscoli e capelli rossi da sogno.", "." },
  ["fe61e2b57b5ca103"] = { "Cavalieri dei montoni, IN RIGA!", "." },
  ["fe753413db9afb9c"] = { "Troverai l'anziano Radastella fuori dai cancelli di ⟦Zul'Gurub=Zul'gurub⟧, nella Valle di Rovotorto.", "." },
  ["fe757cd44dde39c5"] = { "Ora mi serve solo un lazo d'oro.", "." },
  ["fe75e938357cdb33"] = { "Se cerchi un cacciatore, allora devi andare da Dazalar. Di solito lo trovi appena fuori dalla locanda di Dolanaar.", "." },
  ["fe7ac6d502602c90"] = { "Oggi è proprio il tuo giorno fortunato: ho appena finito la manutenzione del Super-Seller 680. Ci sono tonnellate di articoli in vendita a prezzi bassi-bassissimi. Avanti, guarda tu stess<o/a>... mio fratello Cork crede che il suo ⟦Vendor-Tron 1000=Venditron 1000⟧ venderà più del mio robot.", "." },
  ["fe81d9d8f17d316f"] = { "Alamorte, o Neltharion, come era conosciuto un tempo, era l'Aspetto che incarnava la forza del mondo: il ⟦Titan=Titano⟧ plasmatore noto come Khaz'goroth, Forgiatore del mondo, gli aveva concesso un potere quasi illimitato su questo regno mortale.\n\nCon il tradimento e l'inganno, l'immondo convinse gli altri quattro Aspetti a infondere i loro poteri in un oggetto noto come Demon Soul, indebolendoli gravemente e seminando la divisione fra gli Aspetti, un tempo così grandi.", "." },
  ["fe98a3e197e31222"] = { "Il ⟦Stonehearth Bunker=Fortilizio di Cordipietra⟧ protegge il fianco orientale del ⟦Field of Strife=Pian della Discordia⟧.\n\nÈ controllato dall'⟦Horde=Orda⟧.", "." },
  ["fea2e95f9b782a00"] = { "Ho bisogno di addestramento da guerriero.", "." },
  ["fea351317c82ebbe"] = { "Ehilà, ehilà, ehilà! Se vuoi mettere alla prova le tue abilità di pesca, ho proprio il posto che fa per te! Questa domenica c'è un torneo di pesca a Rovotorto!", "." },
  ["fea5ec0d1053603f"] = { "Vorrei comprare altri semi di Tharlendris.", "." },
  ["feb161324e218922"] = { "Un ⟦Alliance Commendation Signet=Anello d'Encomio dell'Alleanza⟧ viene conferito a <un/una> <eroe/eroina> che va ben oltre il proprio dovere verso l'⟦Alliance=Alleanza⟧. In tutte le capitali si trovano vari ufficiali dell'encomio per le fazioni dell'⟦Alliance=Alleanza⟧: parla con quello della fazione con cui vuoi aumentare la reputazione, e dagli il numero di anelli che ti chiede!\n\nA proposito, durante lo sforzo bellico qui, se per i tuoi anelli preferisci una ricompensa materiale invece della reputazione, cerca il primo maresciallo Nevealta.", "." },
  ["feb261ded75e7d5d"] = { "%s inizia a creparsi e ad aprirsi...", "." },
  ["feb9d1be9c8679b2"] = { "Non mi impedirai di fuggire da qui, {race}!", "." },
  ["fec6a7b3dec3c545"] = { "Qui alla loggia dei Farstrider apprezziamo le abilità di caccia sopra ogni cosa. Vuoi ottenere la mia approvazione? Dovrai guadagnartela.\n\nMi sembri all'altezza della sfida, <ragazzo/ragazza>!", "." },
  ["fecce601e55b8904"] = { "Hai fatto meglio di quanto mi aspettassi, {name}, e bene quanto speravo. Ora puoi imparare a comandare l'ombra del Vuoto che hai soggiogato, un alleato che troverai prezioso nelle prove che di certo ti attendono.\n\nPer ora non ho altro da insegnarti, ma con te sono ben lontano dall'aver finito, {name}.", "." },
  ["fed557a6c23b9abe"] = { "E tu cosa hai fatto?", "." },
  ["fed6e23ecb7263b5"] = { "Eh? Salute, giovane {class}. Ci vuole coraggio per arrivare fin qui con tutte quelle creature che vagano nei dintorni!\n\nBeh, ora che sei qui, forse puoi dare una mano a chi vive da eremita...", "." },
  ["feef59dc9f06d473"] = { "Be', di sicuro troverai un addestramento nelle arti magiche nella Hall of Mysteries, a nord delle porte di ⟦Ironforge=Forgiardente⟧. ⟦Juli Stormkettle=Juli Granteiera⟧ è sempre lì, col naso in un libro.", "." },
})
